begin;
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status)
select 'Mountain House Diwali Mela 2026','MH Cultural Events lists a public Diwali celebration on November 7, 2026, 10 AM–5 PM Pacific at Mountain House Central Community Park. The organizer advertises free entry and parking, music, dancing, vendor stalls and family activities, welcoming everyone. Confirm current access and any individual vendor or activity costs before attending. The event header and current community bulletin agree on 2026; the description retains an older year typo. Organizer page checked November 6, 2026. No flyer, photograph or response counts reused.','Mountain House','Central Community Park, 25 Main Street, Mountain House','2026-11-07T10:00:00-08:00'::timestamptz,'2026-11-07T17:00:00-08:00'::timestamptz,'Seasonal celebrations','https://www.facebook.com/events/2283245442502670/','HIGH','approved','editorial_seasonal_2026',0.95,false,'approved'
where not exists(select 1 from public.events where city='Mountain House' and lower(title) like '%diwali%mela%' and start_date='2026-11-07T10:00:00-08:00'::timestamptz);
commit;
